/**
 * Docs: docs/scripts/seed.md
 * SQL seed executor for the Decoder Ring, run by `prisma db seed`.
 *
 * Loads one catalog's SQL files from prisma/seed-sql/<catalog>/ into the database
 * DATABASE_URL names, through the same loader the ECS seed task runs
 * (`loadSeed` in seed-ecs.ts).
 *
 * The catalog is declared, never inferred: SEED_CATALOG=<name> or --catalog=<name>.
 *
 * SQL files are generated by: yarn seed:generate
 */

import {
  requestedCatalog,
  resolveCatalogDir,
  SEED_ROOT,
} from "./catalog-dir.js";
import { loadSeed } from "./seed-ecs.js";

const databaseUrl = process.env.DATABASE_URL;
if (!databaseUrl) {
  throw new Error("DATABASE_URL environment variable is required");
}

await loadSeed({
  databaseUrl,
  seedDir: resolveCatalogDir(SEED_ROOT, requestedCatalog()),
  tag: "seed",
});
